using System.Text;

var builder = WebApplication.CreateBuilder(args);
builder.WebHost.UseUrls(Environment.GetEnvironmentVariable("PAYGUARD_DASHBOARD_URL") ?? "http://127.0.0.1:5078");

var app = builder.Build();

app.MapGet("/api/health", () => Results.Json(new
{
    application = "PayPal Flight Recorder",
    status = "READY",
    version = "0.1"
}));

var html = Encoding.UTF8.GetString(
    Convert.FromBase64String(""));

app.MapGet("/", () => Results.Content(
    html, "text/html", Encoding.UTF8));

var investigations = new System.Collections.Concurrent.ConcurrentDictionary<string, InvestigationState>();

app.MapPost("/api/investigations", () =>
{
    if (investigations.Values.Any(x => x.Status == "RUNNING"))
        return Results.Conflict(new { error = "Investigation already running." });

    var id = Guid.NewGuid().ToString("N");
    var state = new InvestigationState(id);
    investigations[id] = state;

    _ = Task.Run(async () =>
    {
        try
        {
            var packagedDll = Path.Combine(
                AppContext.BaseDirectory,
                "LiveTrace", "PayGuard.LiveTrace.dll");

            var developmentDll = Path.GetFullPath(Path.Combine(
                AppContext.BaseDirectory,
                "../../../../PayGuard.LiveTrace/bin/Debug/net10.0/PayGuard.LiveTrace.dll"));

            var dll = File.Exists(packagedDll) ? packagedDll : developmentDll;

            if (!File.Exists(dll))
                throw new FileNotFoundException("LiveTrace executable missing.", dll);

            var start = new System.Diagnostics.ProcessStartInfo("dotnet")
            {
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            start.ArgumentList.Add(dll);
            start.ArgumentList.Add("--full-investigation");

            using var process = new System.Diagnostics.Process { StartInfo = start };

            if (!process.Start())
                throw new InvalidOperationException("Could not start LiveTrace.");

            var stdout = process.StandardOutput.ReadToEndAsync();
            var stderr = process.StandardError.ReadToEndAsync();

            using var timeout = new CancellationTokenSource(TimeSpan.FromMinutes(3));

            try
            {
                await process.WaitForExitAsync(timeout.Token);
            }
            catch (OperationCanceledException)
            {
                if (!process.HasExited)
                    process.Kill(entireProcessTree: true);
                throw;
            }

            state.Output = await stdout;
            state.Error = await stderr;
            state.Status = process.ExitCode == 0 ? "COMPLETE" : "FAILED";
        }
        catch (Exception ex)
        {
            state.Error = ex.GetType().Name + ": " + ex.Message;
            state.Status = "FAILED";
        }
    });

    return Results.Accepted($"/api/investigations/{id}",
        new { id, status = "RUNNING" });
});

app.MapGet("/api/investigations/{id}", (string id) =>
    investigations.TryGetValue(id, out var state)
        ? Results.Ok(new { state.Id, state.Status, state.Output, state.Error })
        : Results.NotFound());
app.Run();
public sealed class InvestigationState(string id)
{
    public string Id { get; } = id;
    public string Status { get; set; } = "RUNNING";
    public string Output { get; set; } = "";
    public string Error { get; set; } = "";
}
